arguments.command:
cd /tmp/mut && cr-report s.sqlite --show-pending 2>/dev/null | grep -B1 -A0 "SURVIVED" | grep -E "^\S+\.py" ; cosmic-ray dump s.sqlite | python -c "
import sys,json
for l in sys.stdin:
    j=json.loads(l)
    if j[1]['test_outcome']=='survived':
        for m in j[0]['mutations']: print(m['module_path'],m['operator_name'],m['occurrence'],m['start_pos'])"; cat src/payment/domain/money.py

